import unittest
from envconfig import load
class Duplicates(unittest.TestCase):
 def test_default_last_wins(self):self.assertEqual(load(["A=one","A=two"]),{"A":"two"})
 def test_reject_changed_value(self):
  with self.assertRaises(ValueError):load(["A=one","A=two"],reject_duplicates=True)
 def test_reject_same_or_empty_value(self):
  for lines in [["A=one","A=one"],["A=","A="]]:
   with self.subTest(lines=lines),self.assertRaises(ValueError):load(lines,reject_duplicates=True)
 def test_comments_and_iterator(self):self.assertEqual(load(iter(["# comment","","A=one","B=two"]),reject_duplicates=True),{"A":"one","B":"two"})
 def test_case_sensitive(self):self.assertEqual(load(["A=one","a=two"],reject_duplicates=True),{"A":"one","a":"two"})

from envsyntax import parse_entry

def load(lines, *, reject_duplicates=False):
    config = {}
    for line in lines:
        entry = parse_entry(line)
        if entry is None:
            continue
        key, value = entry
        if reject_duplicates and key in config:
            raise ValueError(f"duplicate key: {key}")
        config[key] = value
    return config
